package decimal

// LN10 and PI to 1025 digits, taken verbatim from decimal.js. The series-based
// functions round these down to the working precision, and refuse to run past
// them: asking for more digits than the constants hold is the one place
// decimal.js raises a precision-limit error.
const (
	ln10Digits = "2."
	piDigits   = "3."
)

// The usable precision of each constant is its digit count without the point.
const (
	ln10Precision = len(ln10Digits) - 1
	piPrecision   = len(piDigits) - 1
)
